import pytest


def test_simple_format_usd():
    """Simple USD amount formatting"""
    exponents = {'USD': 2}
    assert impl.format_amount('1.23', 'USD', exponents) == '1.23'
    assert impl.format_amount('10', 'USD', exponents) == '10.00'
    assert impl.format_amount('100.1', 'USD', exponents) == '100.10'


def test_simple_format_jpy():
    """JPY amount with no minor units"""
    exponents = {'JPY': 0}
    assert impl.format_amount('1234', 'JPY', exponents) == '1234'
    assert impl.format_amount('1234.5', 'JPY', exponents) == '1234'


def test_three_decimal_currency():
    """Gulf currency with 3 decimal places"""
    exponents = {'KWD': 3}
    assert impl.format_amount('1.234', 'KWD', exponents) == '1.234'
    assert impl.format_amount('1.2', 'KWD', exponents) == '1.200'


def test_rounding_half_even_up():
    """2.675 USD rounds to 2.68 (banker's rounding to even)"""
    exponents = {'USD': 2}
    assert impl.format_amount('2.675', 'USD', exponents) == '2.68'


def test_rounding_half_even_down():
    """2.665 USD rounds to 2.66 (banker's rounding to even)"""
    exponents = {'USD': 2}
    assert impl.format_amount('2.665', 'USD', exponents) == '2.66'


def test_rounding_clear_cases():
    """Non-halfway rounding cases"""
    exponents = {'USD': 2}
    assert impl.format_amount('1.234', 'USD', exponents) == '1.23'
    assert impl.format_amount('1.236', 'USD', exponents) == '1.24'


def test_scientific_notation():
    """Scientific notation input and various exponent formats"""
    exponents = {'USD': 2}
    assert impl.format_amount('1E+2', 'USD', exponents) == '100.00'
    assert impl.format_amount('1.5e-3', 'USD', exponents) == '0.00'
    assert impl.format_amount('1.5E+1', 'USD', exponents) == '15.00'


def test_whitespace_handling():
    """Input with leading and trailing whitespace"""
    exponents = {'USD': 2}
    assert impl.format_amount('  1.23  ', 'USD', exponents) == '1.23'
    assert impl.format_amount('  10  ', 'USD', exponents) == '10.00'


def test_zero_formatting():
    """Zero input in different currencies"""
    exponents = {'USD': 2, 'JPY': 0}
    assert impl.format_amount('0', 'USD', exponents) == '0.00'
    assert impl.format_amount('0', 'JPY', exponents) == '0'
    assert impl.format_amount('0.0', 'USD', exponents) == '0.00'


def test_negative_zero():
    """Negative amounts that round to zero become unsigned"""
    exponents = {'USD': 2, 'JPY': 0}
    assert impl.format_amount('-0.004', 'USD', exponents) == '0.00'
    assert impl.format_amount('-0.4', 'JPY', exponents) == '0'


def test_negative_amounts():
    """Negative amounts maintain sign and round symmetrically"""
    exponents = {'USD': 2, 'JPY': 0}
    assert impl.format_amount('-1.23', 'USD', exponents) == '-1.23'
    assert impl.format_amount('-2.675', 'USD', exponents) == '-2.68'
    assert impl.format_amount('-1234', 'JPY', exponents) == '-1234'


def test_large_amounts():
    """Very large amounts without scientific notation in output"""
    exponents = {'USD': 2}
    assert impl.format_amount('999999999.99', 'USD', exponents) == '999999999.99'
    assert impl.format_amount('1.5E+10', 'USD', exponents) == '15000000000.00'


def test_explicit_plus_sign():
    """Input with explicit plus sign (no leading + in output)"""
    exponents = {'USD': 2}
    assert impl.format_amount('+1.23', 'USD', exponents) == '1.23'
    assert impl.format_amount('+100', 'USD', exponents) == '100.00'


def test_exponent_variations():
    """Different exponent values (1, 4) with rounding"""
    exponents = {'TEST1': 1, 'TEST4': 4}
    assert impl.format_amount('1.25', 'TEST1', exponents) == '1.2'
    assert impl.format_amount('1.35', 'TEST1', exponents) == '1.4'
    assert impl.format_amount('1.23456', 'TEST4', exponents) == '1.2346'


def test_unknown_currency_raises_keyerror():
    """Unknown currency raises KeyError before parsing amount"""
    exponents = {'USD': 2}
    with pytest.raises(KeyError):
        impl.format_amount('1.23', 'XXX', exponents)
    # KeyError takes precedence even if amount is invalid
    with pytest.raises(KeyError):
        impl.format_amount('invalid', 'XXX', exponents)


def test_invalid_amount_errors():
    """Various unparseable amounts raise ValueError"""
    exponents = {'USD': 2}
    with pytest.raises(ValueError):
        impl.format_amount('', 'USD', exponents)
    with pytest.raises(ValueError):
        impl.format_amount('abc', 'USD', exponents)
    with pytest.raises(ValueError):
        impl.format_amount('1.2.3', 'USD', exponents)
    with pytest.raises(ValueError):
        impl.format_amount('12,34', 'USD', exponents)
    with pytest.raises(ValueError):
        impl.format_amount('$1.00', 'USD', exponents)


def test_non_finite_errors():
    """Non-finite values (NaN, Infinity) raise ValueError"""
    exponents = {'USD': 2}
    with pytest.raises(ValueError):
        impl.format_amount('NaN', 'USD', exponents)
    with pytest.raises(ValueError):
        impl.format_amount('Infinity', 'USD', exponents)
    with pytest.raises(ValueError):
        impl.format_amount('-Infinity', 'USD', exponents)
